const SCHEMES = [
  { id: 'system', label: { zh: '跟随系统', en: 'System' } },
  { id: 'light', label: { zh: '浅色', en: 'Light' } },
  { id: 'dark', label: { zh: '深色', en: 'Dark' } },
]

/** Build the {light, dark} override map the theme service validates. */
function overridesFor(fam) {
  if (!fam || !fam.light) return null
  const names = new Set([...Object.keys(fam.light), ...Object.keys(fam.dark)])
  const out = {}
  for (const n of names) out[n] = { light: fam.light[n] || fam.dark[n], dark: fam.dark[n] || fam.light[n] }
  return out
}

